ALTER TABLE posts ADD COLUMN source_memory_id uuid,ADD COLUMN source_memory_version integer,ADD COLUMN source_excerpt text,ADD COLUMN world_context_ref jsonb,ADD COLUMN generation_job_id uuid;
DO $$ DECLARE c record;BEGIN FOR c IN SELECT conname FROM pg_constraint WHERE conrelid='posts'::regclass AND contype='c' AND pg_get_constraintdef(oid) LIKE '%world_notice%' LOOP EXECUTE format('ALTER TABLE posts DROP CONSTRAINT %I',c.conname);END LOOP;END $$;
ALTER TABLE posts ADD CONSTRAINT posts_kind_scope CHECK(kind IN ('user','world_notice','memory_echo'));
ALTER TABLE posts ADD CONSTRAINT posts_source_shape CHECK(COALESCE(
 (kind='user' AND client_post_id IS NOT NULL AND request_hash ~ '^[a-f0-9]{64}$' AND char_length(body) BETWEEN 1 AND 500 AND person_id IS NULL AND world_id IS NULL AND source_movement_id IS NULL AND source_world_version IS NULL AND source_movement IS NULL AND source_hash IS NULL AND source_memory_id IS NULL AND source_memory_version IS NULL AND source_excerpt IS NULL AND generation_job_id IS NULL AND world_context_ref IS NULL)
 OR (kind='world_notice' AND client_post_id IS NULL AND request_hash IS NULL AND body='' AND person_id IS NOT NULL AND world_id IS NOT NULL AND source_movement_id IS NOT NULL AND source_world_version>1 AND source_hash ~ '^[a-f0-9]{64}$' AND jsonb_typeof(source_movement)='object' AND source_movement->>'id'=source_movement_id::text AND (source_movement->>'worldVersion')::integer=source_world_version AND source_movement->'toWorld'->>'id'=world_id::text AND jsonb_typeof(source_movement->'fromWorld')='object' AND jsonb_typeof(source_movement->'toWorld')='object' AND source_memory_id IS NULL AND source_memory_version IS NULL AND source_excerpt IS NULL AND generation_job_id IS NULL AND world_context_ref IS NULL)
 OR (kind='memory_echo' AND client_post_id IS NULL AND request_hash IS NULL AND char_length(body) BETWEEN 1 AND 1200 AND person_id IS NOT NULL AND world_id IS NOT NULL AND source_movement_id IS NULL AND source_world_version IS NULL AND source_movement IS NULL AND source_hash IS NULL AND source_memory_id IS NOT NULL AND source_memory_version>0 AND char_length(source_excerpt) BETWEEN 1 AND 320 AND generation_job_id IS NOT NULL AND jsonb_typeof(world_context_ref)='object' AND world_context_ref->>'reality'='virtual' AND world_context_ref->>'branch'='main' AND world_context_ref->>'personId'=person_id::text AND world_context_ref->'currentWorld'->>'id'=world_id::text),false));
CREATE UNIQUE INDEX echo_source_version ON posts(account_id,source_memory_id,source_memory_version) WHERE kind='memory_echo';
CREATE UNIQUE INDEX echo_active_source ON posts(account_id,source_memory_id) WHERE kind='memory_echo' AND status='active';
CREATE TABLE social_memory_sources(account_id uuid NOT NULL REFERENCES social_account_write_gates(account_id),person_id uuid NOT NULL,memory_id uuid NOT NULL,source_version integer NOT NULL CHECK(source_version>0),state text NOT NULL CHECK(state IN ('active','removed')),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(account_id,memory_id),CHECK(created_at<=updated_at));
CREATE TABLE social_memory_receipts(account_id uuid NOT NULL REFERENCES social_account_write_gates(account_id),event_id uuid NOT NULL,request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'),outcome text NOT NULL CHECK(outcome IN ('accepted','stale','ineligible','removed')),created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(account_id,event_id));
CREATE TABLE social_generation_jobs(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES social_account_write_gates(account_id),person_id uuid NOT NULL,memory_id uuid NOT NULL,memory_version integer NOT NULL CHECK(memory_version>0),kind text NOT NULL CHECK(kind IN ('memory_echo','feed_reaction')),post_id uuid,source_comment_id uuid,source_comment_version integer,
 person_version integer NOT NULL CHECK(person_version>0),person_access_version integer NOT NULL CHECK(person_access_version>0),account_access_version integer NOT NULL CHECK(account_access_version>0),authorization_version integer NOT NULL CHECK(authorization_version>0),ai_authorization_version integer NOT NULL CHECK(ai_authorization_version>0),
 state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','succeeded','failed','blocked','canceled')),version integer NOT NULL DEFAULT 1 CHECK(version>0),dispatch_id uuid NOT NULL,dispatch_generation integer NOT NULL DEFAULT 1 CHECK(dispatch_generation>0),attempt_id uuid,attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count BETWEEN 0 AND 3),lease_until timestamptz(3),failure_code text,retryable boolean NOT NULL DEFAULT false,result_id uuid,world_context_ref jsonb,context_comment_refs jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(context_comment_refs)='array' AND jsonb_array_length(context_comment_refs)<=16),
 created_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),queued_at timestamptz(3) NOT NULL DEFAULT clock_timestamp(),started_at timestamptz(3),finished_at timestamptz(3),UNIQUE(account_id,id),
 FOREIGN KEY(account_id,post_id) REFERENCES posts(account_id,id),FOREIGN KEY(account_id,post_id,source_comment_id) REFERENCES post_comments(account_id,post_id,id),
 CHECK((kind='memory_echo' AND post_id IS NULL AND source_comment_id IS NULL AND source_comment_version IS NULL) OR (kind='feed_reaction' AND post_id IS NOT NULL AND source_comment_id IS NOT NULL AND source_comment_version>0)),
 CHECK((state='running')=(lease_until IS NOT NULL)),CHECK(state<>'running' OR (attempt_id IS NOT NULL AND started_at IS NOT NULL AND lease_until>started_at)),CHECK((state IN ('succeeded','failed','blocked','canceled'))=(finished_at IS NOT NULL)),CHECK(NOT retryable OR state='failed'),CHECK(created_at<=updated_at));
CREATE UNIQUE INDEX social_echo_job_once ON social_generation_jobs(account_id,memory_id,memory_version) WHERE kind='memory_echo';
CREATE UNIQUE INDEX social_comment_job_once ON social_generation_jobs(account_id,source_comment_id,person_id) WHERE kind='feed_reaction';
CREATE UNIQUE INDEX social_one_running_person ON social_generation_jobs(account_id,person_id) WHERE state='running';
ALTER TABLE posts ADD CONSTRAINT social_echo_job_fk FOREIGN KEY(account_id,generation_job_id) REFERENCES social_generation_jobs(account_id,id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE post_comments ALTER COLUMN client_comment_id DROP NOT NULL,ALTER COLUMN request_hash DROP NOT NULL,ADD COLUMN author_kind text NOT NULL DEFAULT 'self',ADD COLUMN person_id uuid,ADD COLUMN display_name text,ADD COLUMN generation_job_id uuid;
ALTER TABLE post_comments ADD CONSTRAINT social_comment_actor CHECK(COALESCE((author_kind='self' AND person_id IS NULL AND display_name IS NULL AND generation_job_id IS NULL AND client_comment_id IS NOT NULL AND request_hash ~ '^[a-f0-9]{64}$') OR (author_kind='persona' AND person_id IS NOT NULL AND char_length(display_name) BETWEEN 1 AND 200 AND generation_job_id IS NOT NULL AND client_comment_id IS NULL AND request_hash IS NULL AND reply_to_comment_id IS NOT NULL),false)),ADD CONSTRAINT social_comment_job_fk FOREIGN KEY(account_id,generation_job_id) REFERENCES social_generation_jobs(account_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE UNIQUE INDEX social_one_ai_comment_job ON post_comments(account_id,generation_job_id) WHERE author_kind='persona';
CREATE TRIGGER social_sources_guard BEFORE INSERT OR UPDATE ON social_memory_sources FOR EACH ROW EXECUTE FUNCTION social_payload_write_guard();
CREATE TRIGGER social_receipts_guard BEFORE INSERT OR UPDATE ON social_memory_receipts FOR EACH ROW EXECUTE FUNCTION social_payload_write_guard();
CREATE TRIGGER social_jobs_guard BEFORE INSERT OR UPDATE ON social_generation_jobs FOR EACH ROW EXECUTE FUNCTION social_payload_write_guard();
CREATE FUNCTION social_retire_comment_dependents() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='active' AND NEW.status='removed' THEN UPDATE post_comments c SET status='removed',removed_at=clock_timestamp(),updated_at=clock_timestamp(),version=version+1 WHERE c.account_id=NEW.account_id AND c.post_id=NEW.post_id AND c.author_kind='persona' AND c.status='active' AND EXISTS(SELECT 1 FROM social_generation_jobs j,jsonb_array_elements(j.context_comment_refs) r WHERE j.account_id=c.account_id AND j.id=c.generation_job_id AND r->>'id'=NEW.id::text);END IF;RETURN NEW;END $$;
CREATE TRIGGER social_comment_dependents AFTER UPDATE ON post_comments FOR EACH ROW EXECUTE FUNCTION social_retire_comment_dependents();
ALTER TABLE social_commands DROP CONSTRAINT social_commands_operation_check;
ALTER TABLE social_commands ADD CONSTRAINT social_commands_operation_check CHECK(operation IN ('create','remove','react','comment','remove_comment','generation_retry','generation_cancel'));
ALTER TABLE social_generation_jobs ADD CONSTRAINT social_job_person_unique UNIQUE(account_id,person_id,id);
ALTER TABLE posts ADD CONSTRAINT social_echo_person_job_fk FOREIGN KEY(account_id,person_id,generation_job_id) REFERENCES social_generation_jobs(account_id,person_id,id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE post_comments ADD CONSTRAINT social_comment_person_job_fk FOREIGN KEY(account_id,person_id,generation_job_id) REFERENCES social_generation_jobs(account_id,person_id,id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE posts ADD CONSTRAINT social_echo_world_shape CHECK(kind<>'memory_echo' OR COALESCE(world_context_ref->>'accountId'=account_id::text AND world_context_ref->>'personId'=person_id::text AND world_context_ref->>'reality'='virtual' AND world_context_ref->>'branch'='main' AND (world_context_ref->>'personVersion')::integer>0 AND (world_context_ref->>'worldVersion')::integer>0 AND world_context_ref->'currentWorld'->>'id'=world_id::text AND (world_context_ref->'currentWorld'->>'catalogVersion')::integer>0 AND jsonb_typeof(world_context_ref->'currentWorld'->'enabled')='boolean' AND char_length(world_context_ref->'currentWorld'->>'code')>0 AND char_length(world_context_ref->'currentWorld'->>'displayName')>0 AND world_context_ref->>'revision' ~ '^[a-f0-9]{64}$' AND jsonb_typeof(world_context_ref->'recentMovements')='array',false));
CREATE FUNCTION social_generation_binding() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE j social_generation_jobs%ROWTYPE;BEGIN
 IF NEW.generation_job_id IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO j FROM social_generation_jobs WHERE account_id=NEW.account_id AND id=NEW.generation_job_id;
 IF NOT FOUND OR j.person_id<>NEW.person_id THEN RAISE EXCEPTION 'Wrong generated actor.' USING ERRCODE='23514';END IF;
 IF TG_TABLE_NAME='posts' THEN
 IF j.kind<>'memory_echo' OR j.memory_id<>NEW.source_memory_id OR j.memory_version<>NEW.source_memory_version THEN RAISE EXCEPTION 'Wrong memory echo source.' USING ERRCODE='23514';END IF;
 ELSE
 IF j.kind<>'feed_reaction' OR j.post_id<>NEW.post_id OR j.source_comment_id<>NEW.reply_to_comment_id THEN RAISE EXCEPTION 'Wrong comment reply source.' USING ERRCODE='23514';END IF;
 END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER social_post_generation_binding AFTER INSERT OR UPDATE ON posts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION social_generation_binding();
CREATE CONSTRAINT TRIGGER social_comment_generation_binding AFTER INSERT OR UPDATE ON post_comments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION social_generation_binding();
CREATE FUNCTION social_immutable_echo() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.kind='memory_echo' AND (NEW.kind,NEW.account_id,NEW.person_id,NEW.world_id,NEW.body,NEW.source_memory_id,NEW.source_memory_version,NEW.source_excerpt,NEW.world_context_ref,NEW.generation_job_id,NEW.created_at) IS DISTINCT FROM (OLD.kind,OLD.account_id,OLD.person_id,OLD.world_id,OLD.body,OLD.source_memory_id,OLD.source_memory_version,OLD.source_excerpt,OLD.world_context_ref,OLD.generation_job_id,OLD.created_at) THEN RAISE EXCEPTION 'Committed echo source and content are immutable.' USING ERRCODE='23514';END IF;
 RETURN NEW;END $$;
CREATE TRIGGER social_echo_immutable BEFORE UPDATE ON posts FOR EACH ROW EXECUTE FUNCTION social_immutable_echo();
CREATE FUNCTION social_immutable_comment_content() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (NEW.account_id,NEW.post_id,NEW.body,NEW.author_kind,NEW.person_id,NEW.display_name,NEW.reply_to_comment_id,NEW.generation_job_id,NEW.created_at) IS DISTINCT FROM (OLD.account_id,OLD.post_id,OLD.body,OLD.author_kind,OLD.person_id,OLD.display_name,OLD.reply_to_comment_id,OLD.generation_job_id,OLD.created_at) THEN RAISE EXCEPTION 'Comment source and content are immutable.' USING ERRCODE='23514';END IF;
 RETURN NEW;END $$;
CREATE TRIGGER social_comment_content_immutable BEFORE UPDATE ON post_comments FOR EACH ROW EXECUTE FUNCTION social_immutable_comment_content();
